import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.DF1tCImu.js";const u=JSON.parse('{"title":"Code graph","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/code-graph.md","filePath":"docs/agents/code-graph.md"}'),r={name:"docs/agents/code-graph.md"};function n(d,e,i,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="code-graph" tabindex="-1">Code graph <a class="header-anchor" href="#code-graph" aria-label="Permalink to &quot;Code graph&quot;">​</a></h1><p>The environment every thread runs in has <a href="https://github.com/colbymchenry/codegraph" target="_blank" rel="noreferrer">CodeGraph</a> installed: a local index of the Kotlin, Swift and TypeScript code (symbols, calls, who depends on what). It answers &quot;how does X work&quot; or &quot;what breaks if I change Y&quot; in one call instead of many greps and file reads.</p><h2 id="use-it" tabindex="-1">Use it <a class="header-anchor" href="#use-it" aria-label="Permalink to &quot;Use it&quot;">​</a></h2><ul><li><strong>Main thread</strong>: call the <code>codegraph_explore</code> MCP tool with a question or a symbol or file name. It returns the relevant source, the call paths and the blast radius (callers and tests).</li><li><strong>Subagents, or if the MCP tool is missing</strong>: run <code>codegraph explore &quot;&lt;question&gt;&quot;</code> or <code>codegraph node &lt;symbol|file&gt;</code> in Bash. If the repo has no index yet, run <code>codegraph init</code> once (about 6 s here).</li><li>Use it to find code and see impact before a change. Still read the files you edit, and still follow <code>CONTEXT.md</code> for naming. The graph knows code, not decisions: ADRs and docs stay the source of truth.</li><li>Never commit <code>.codegraph/</code>; it ignores itself.</li></ul><h2 id="where-it-is-set-up" tabindex="-1">Where it is set up <a class="header-anchor" href="#where-it-is-set-up" aria-label="Permalink to &quot;Where it is set up&quot;">​</a></h2><ul><li><strong>Install and index</strong>: the environment&#39;s setup script installs <code>codegraph</code> and runs <code>codegraph init</code> in the repo folder, so every new thread starts with an index.</li><li><strong>MCP server</strong>: the environment&#39;s setup script registers it at user level with <code>claude mcp add --scope user codegraph -- codegraph serve --mcp</code>. That gives the main thread the <code>codegraph_explore</code> tool and keeps the index in sync as files change. <code>claude mcp list</code> should show <code>codegraph</code> as connected. If the tool is missing in a thread, say so and use the CLI.</li><li><strong>Why not a repo <code>.mcp.json</code></strong>: a project-scoped server stays &quot;Pending approval&quot; until someone approves it, and a cloud thread cannot answer that prompt, even with <code>enabledMcpjsonServers</code> set. A user-level server needs no approval.</li><li><strong>Copilot cloud agent</strong>: <code>.github/workflows/copilot-setup-steps.yml</code> installs <code>codegraph</code> and runs <code>codegraph init</code>. It has no MCP server, so it uses the CLI.</li><li>To change the version or the install, edit the environment, and the version in <code>copilot-setup-steps.yml</code>.</li></ul>',6)])])}const g=o(r,[["render",n]]);export{u as __pageData,g as default};
